CREATE FUNCTION public.fn_set_google_data_expiry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.expires_at IS NULL THEN
        NEW.expires_at := NEW.scraped_at + INTERVAL '30 days';
    END IF;
    RETURN NEW;
END; $$;


